function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // two stick figures
  let figure1X = W / 2 - 100 + Math.sin(t) * 50;
  let figure2X = W / 2 + 100 - Math.sin(t) * 50;

  // draw figure 1
  ctx.beginPath();
  ctx.arc(figure1X, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure1X, H / 2 + 20);
  ctx.lineTo(figure1X, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure1X, H / 2 + 50);
  ctx.lineTo(figure1X - 30, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure1X, H / 2 + 50);
  ctx.lineTo(figure1X + 30, H / 2 + 70);
  ctx.stroke();

  // draw figure 2
  ctx.beginPath();
  ctx.arc(figure2X, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure2X, H / 2 + 20);
  ctx.lineTo(figure2X, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure2X, H / 2 + 50);
  ctx.lineTo(figure2X - 30, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(figure2X, H / 2 + 50);
  ctx.lineTo(figure2X + 30, H / 2 + 70);
  ctx.stroke();

  // line connecting them
  ctx.beginPath();
  ctx.moveTo(figure1X, H / 2 + 50);
  ctx.lineTo(figure2X, H / 2 + 50);
  ctx.setLineDash([10 - Math.abs(Math.sin(t) * 10), 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.restore();
}
